<x-admin.confirmation :application="$application" title="Restore application"
    :description="$application['machine'] ? 'The service will return to Testing. Token issuance remains blocked until a separate operator approval activates it. Previous tokens remain invalid; restoration never grants API permissions or resource access.' : ($application['owner_id'] === null ? 'No owner is assigned; nobody can sign in while this app is Testing until ownership is assigned separately. ' : '').'The application will return to Testing, where only its owner can sign in. Previous tokens and pending sign-ins will remain invalid. Web, Browser and Mobile application owners can choose Go live separately from their developer settings.'"
    confirmation="I understand and want to restore this application to Testing."
    :action="route('admin.apps.restore', $application['id'])" />
